20	// Config supplies the shared command options and the assembly package's
21	// storage and hosted-sync operations. Dependencies are per invocation, never
22	// global hooks.
23	type Config struct {
24		base.Options
25		Deps Deps
26	}
27	
28	// Deps keeps the connect command independent of command assembly, repo
29	// identity resolution, and the hosted sync engine. The assembly package
30	// supplies these operations so connect drives the same sync loop and push-hook
31	// management as the background triggers.
32	type Deps struct {
33		RepoStoragePaths   func(context.Context, base.CommandRunner, base.EntireEnv, string) (base.RepoStorage, error)
34		AgentSurfaceTarget func(base.Options, []string) string
35		// InstallPushHook installs the pre-push upload hook; sharedHooksDir
36		// reports a core.hooksPath shared across repos, where the hook is not
37		// managed.
38		InstallPushHook func(ctx context.Context, opts base.Options, repoDir string) (sharedHooksDir bool, hookPath string, err error)
39		// HostedFactsSyncAndPull runs one hosted sync for the repo; attempted
40		// reports whether the gates passed and the server was contacted,
41		// pullSucceeded whether the pull half completed.
42		HostedFactsSyncAndPull func(ctx context.Context, errW io.Writer, opts base.Options, repoDir string, storage base.RepoStorage) (attempted, pullSucceeded bool, err error)
43	}
44	
45	// minHostCLIVersion is the first host CLI release that ships `entire repo view
46	// --json` (entireio/cli#2758), which placement resolution depends on. Only
47	// connect's placement shell-out checks it: local-only brain use and explicit
48	// --repo-id/--api-url never touch the host CLI version. Empty disables the
49	// gate explicitly. A var so tests can exercise the gate.
50	var minHostCLIVersion = "0.11.6"
51	
52	// hostedPlacement is the slice of the host CLI's `entire repo view --json`
53	// output this plugin needs (entireio/cli#2758): the repo's region-local ULID
54	// and its cell API base URL, both top-level fields.
55	type hostedPlacement struct {
56		RepoID string `json:"repoId"`
57		APIURL string `json:"apiUrl"`
58	}
59	
60	type connectOptions struct {
61		repoID string
62		apiURL string
63	}
64	
65	func New(cfg Config) *cobra.Command {
66		var connectOpts connectOptions
67		cmd := &cobra.Command{
68			Use:   "connect",
69			Short: "Bind this repository to its hosted brain explicitly",
70			Long: `connect binds this repository to its hosted brain: it records the repo id and
71	API base URL (non-secrets only — the host CLI's own login mints a fresh token
72	per sync), then runs one immediate sync so the first pull happens right away.
73	
74	Running connect (or the onboarding flow) is the ONLY way a repository starts
75	syncing: by default memories stay local and background triggers never connect
76	a repo on their own. Placement resolves through the host CLI (entire repo
77	view); pass --repo-id and --api-url to bypass resolution — a non-default cell
78	or a staging target. Re-running connect re-joins after 'entire brain
79	disconnect'.`,
80			Args: cobra.NoArgs,
81			RunE: func(cmd *cobra.Command, args []string) error {
82				return runConnect(cmd, cfg, connectOpts)
83			},
84		}
85		cmd.Flags().StringVar(&connectOpts.repoID, "repo-id", "", "Hosted repo id (region-local ULID)")
86		cmd.Flags().StringVar(&connectOpts.apiURL, "api-url", "", "Entire API base URL, https://")
87		return cmd
88	}
89	
90	func runConnect(cmd *cobra.Command, cfg Config, connectOpts connectOptions) error {
91		ctx := cmd.Context()
92		opts := cfg.Options
93		repoDir, local, err := base.ResolveLocalTargetRepoDir(ctx, opts.Runner, cfg.Deps.AgentSurfaceTarget(opts, nil))
94		if err != nil {
95			return err
96		}
97		if !local {
98			return fmt.Errorf("connect requires a local repository path")
99		}
100		storage, err := cfg.Deps.RepoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
101		if err != nil {
102			return err
103		}
104	
105		repoID := strings.TrimSpace(connectOpts.repoID)
106		apiURL := strings.TrimSpace(connectOpts.apiURL)
107		if repoID == "" || apiURL == "" {
108			resolved, placementErr := resolveHostedPlacement(ctx, opts.Runner, repoDir)
109			if placementErr != nil {
110				// An already-connected (or disconnected — the opt-out keeps its
111				// coordinates) repo stays re-connectable without flags: re-connect
112				// means re-sync, not re-resolve.
113				if existing, present, readErr := brainstore.ReadHostedRepoBinding(storage.BrainDir); readErr == nil && present && existing.RepoID != "" {
114					resolved = hostedPlacement{RepoID: existing.RepoID, APIURL: existing.BaseURL}
115				} else {
116					// The hint sits on its own line: the host CLI's message ends
117					// with a newline of its own, so a "; pass ..." suffix used to
118					// dangle on a line starting with ";".
119					return fmt.Errorf("connect: %w\nOr pass --repo-id and --api-url explicitly", placementErr)
120				}
121			}
122			if repoID == "" {
123				repoID = resolved.RepoID
124			}
125			if apiURL == "" {
126				apiURL = resolved.APIURL
127			}
128		}
129		// Whether this run re-affirms an existing connection decides the success
130		// headline: "connected" must not read like a state change when nothing
131		// changed.
132		existing, existingPresent, existingErr := brainstore.ReadHostedRepoBinding(storage.BrainDir)
133		binding, err := bindHostedRepo(storage.BrainDir, repoID, apiURL)
134		if err != nil {
135			return fmt.Errorf("connect: %w", err)
136		}
137		already := existingErr == nil && existingPresent && !existing.OptedOut &&
138			existing.RepoID == binding.RepoID && existing.BaseURL == binding.BaseURL
139		// A connected repo wants the push-beat upload: install our pre-push hook
140		// (chained beside whatever hook owns the slot). Best-effort — a hook
141		// problem must not fail the connect.
142		if sharedHooksDir, hookPath, hookErr := cfg.Deps.InstallPushHook(ctx, opts, repoDir); hookErr != nil {
143			fmt.Fprintf(cmd.ErrOrStderr(), "connect: push hook not installed (uploads ride the daemon tick): %v\n", hookErr)
144		} else if sharedHooksDir {
145			fmt.Fprintf(cmd.ErrOrStderr(), "connect: core.hooksPath (%s) is shared across repos; push hook not managed — uploads ride the daemon tick\n", hookPath)
146		}
147		// The kill switch suppresses every sync this command is about to promise,
148		// so say that instead of "now syncing". The binding still gets recorded:
149		// the environment only subtracts, and unsetting it resumes syncing.
150		if base.BrainNoEgressMode() {
151			cmdutil.RenderHostedBanner(cmd.OutOrStdout(),
152				"Connected: "+storage.Key+" — but nothing syncs while "+base.NoEgressToggleName()+" is set",
153				"The binding is recorded and memories stay local. Unset "+base.NoEgressToggleName()+" to start syncing.")
154			return nil
155		}
156		// Connect doubles as the initial pull so a fresh clone receives team
157		// memories immediately. The sync runs BEFORE the banner so the headline
158		// reports what actually happened: a connect whose first pull failed has
159		// not started syncing, and claiming so hides a dead connection.
160		attempted, pullSucceeded, err := cfg.Deps.HostedFactsSyncAndPull(ctx, cmd.ErrOrStderr(), opts, repoDir, storage)
161		if err != nil {
162			return err
163		}
164		if !pullSucceeded {
165			verdict := "failed"
166			if !attempted {
167				verdict = "did not run"
168			}
169			return fmt.Errorf("connect: %s is bound, but the first sync %s (details above); memories stay local until a sync succeeds — fix the cause and re-run '%s'",
170				storage.Key, verdict, base.BrainInvocation(os.LookupEnv, "connect"))
171		}
172		headline := "Connected: " + storage.Key + " is now syncing memories"
173		if already {
174			headline = "Already connected: " + storage.Key + " — memories are syncing"
175		}
176		cmdutil.RenderHostedBanner(cmd.OutOrStdout(), headline,
177			"Memories sync periodically, at session end, and on git push. Teammates' memories merge into this repo's local brain.")
178		return nil
179	}
180	
181	// normalizeHostedBinding validates the target and strips a quoted /api/v1
182	// suffix. Cell URLs are commonly quoted with that prefix (repo view's apiUrl,
183	// docs examples), but the factsync client appends /api/v1/repos/... itself —
184	// storing the suffix would 404 every sync. OptedOut is false: a fresh binding
185	// is an opt-in.
186	func normalizeHostedBinding(repoID, apiURL string) (brainstore.HostedRepoBinding, error) {
187		if strings.TrimSpace(repoID) == "" {
188			return brainstore.HostedRepoBinding{}, fmt.Errorf("hosted repo id is empty")
189		}
190		validated, err := apiurl.Validate(apiURL)
191		if err != nil {
192			return brainstore.HostedRepoBinding{}, err
193		}
194		return brainstore.HostedRepoBinding{RepoID: strings.TrimSpace(repoID), BaseURL: strings.TrimSuffix(validated, "/api/v1")}, nil
195	}
196	
197	// bindHostedRepo is the EXPLICIT connect write: it overwrites whatever is
198	// there, including an opt-out — running connect is how the user opts back in.
199	func bindHostedRepo(brainDir, repoID, apiURL string) (brainstore.HostedRepoBinding, error) {
200		binding, err := normalizeHostedBinding(repoID, apiURL)
201		if err != nil {
202			return brainstore.HostedRepoBinding{}, err
203		}
204		if err := brainstore.WriteHostedRepoBinding(brainDir, binding); err != nil {
205			return brainstore.HostedRepoBinding{}, err
206		}
207		return binding, nil
208	}
209	
210	// ResolveBinding resolves this repo's CURRENT hosted placement through the
211	// host CLI and normalizes it to a writable binding. The background sync uses
212	// it to detect a deleted-and-reonboarded repo behind a stale binding
213	// (COR-2279); it resolves only — writing a binding stays with connect and the
214	// sync's own guarded rebind.
215	func ResolveBinding(ctx context.Context, runner base.CommandRunner, repoDir string) (brainstore.HostedRepoBinding, error) {
216		placement, err := resolveHostedPlacement(ctx, runner, repoDir)
217		if err != nil {
218			return brainstore.HostedRepoBinding{}, err
219		}
220		return normalizeHostedBinding(placement.RepoID, placement.APIURL)
221	}
222	
223	// resolveHostedPlacement shells out to the host CLI for this repo's hosted
224	// placement.
225	func resolveHostedPlacement(ctx context.Context, runner base.CommandRunner, repoDir string) (hostedPlacement, error) {
226		ctx, cancel := context.WithTimeout(ctx, base.HostedShellOutTimeout)
227		defer cancel()
228		if err := checkHostCLIVersion(ctx, runner, repoDir, minHostCLIVersion); err != nil {
229			return hostedPlacement{}, err
230		}
231		stdout, stderr, err := runner.Run(ctx, repoDir, base.HostEntireBinary, "repo", "view", "--json")
232		if err != nil {
233			return hostedPlacement{}, placementFailureError(err, stderr)
234		}
235		var result hostedPlacement
236		if err := base.DecodeHostCLIJSON(stdout, &result); err != nil {
237			return hostedPlacement{}, fmt.Errorf("parse repo view json: %w", err)
238		}
239		return result, nil
240	}
241	
242	// placementFailureError reduces a failed `entire repo view --json` to the line
243	// the host CLI actually said. The runner's wrap carries debug framing — an
244	// argv echo plus the host's "Using context '…'." login banner — that a human
245	// reading connect's failure never needs. Drop the banner, then let
246	// providerdetail.Summary keep the host's Error:-marked or first stderr line.
247	func placementFailureError(runErr error, stderr []byte) error {
248		var kept []string
249		for _, line := range strings.Split(string(stderr), "\n") {
250			line = strings.TrimSpace(line)
251			if line == "" || strings.HasPrefix(line, "Using context ") {
252				continue
253			}
254			kept = append(kept, line)
255		}
256		if summary := providerdetail.Summary(strings.Join(kept, "\n")); summary != "" {
257			return errors.New(summary)
258		}
259		// Nothing usable on stderr: name the command and the cause under the
260		// runner's argv echo (exit status, or a missing host CLI).
261		cause := runErr
262		if unwrapped := errors.Unwrap(runErr); unwrapped != nil {
263			cause = unwrapped
264		}
265		return fmt.Errorf("`entire repo view --json`: %v", cause)
266	}
267	
268	// checkHostCLIVersion refuses placement resolution on a host CLI older than
269	// min, so the failure says "upgrade" instead of repo view's unknown-command
270	// noise. A missing CLI or an unrecognized version line (dev builds) passes:
271	// the repo view call itself is the authority on whether the command exists.
272	func checkHostCLIVersion(ctx context.Context, runner base.CommandRunner, repoDir, min string) error {
273		if min == "" {
274			return nil
275		}
276		stdout, _, err := runner.Run(ctx, repoDir, base.HostEntireBinary, "version")
277		if err != nil {
278			return nil
279		}
280		// First line is "Entire CLI <version>", on some builds with a trailing
281		// "(<commit>)". Take the first field that parses as semver, not a fixed
282		// position, so a build suffix cannot fail-open the gate.
283		line, _, _ := strings.Cut(strings.TrimSpace(string(stdout)), "\n")
284		got := ""
285		for _, field := range strings.Fields(line) {
286			if v := "v" + strings.TrimPrefix(field, "v"); semver.IsValid(v) {
287				got = v
288				break
289			}
290		}
291		if got == "" {
292			return nil
293		}
294		// Compare the release core only: a prerelease or pseudo-version of min
295		// (nightly, git describe) ranks below min in full semver order yet may
296		// already ship repo view — those builds pass and repo view stays the
297		// authority.
298		core := strings.TrimSuffix(got, semver.Build(got))
299		core = strings.TrimSuffix(core, semver.Prerelease(core))
300		if semver.Compare(core, "v"+min) >= 0 {
301			return nil
302		}
303		return fmt.Errorf("entire CLI %s does not support `entire repo view` (needs %s or newer); upgrade the entire CLI and re-run connect", strings.TrimPrefix(got, "v"), min)
304	}
